<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/app/RequiredFile.php';

require_once __DIR__ . '/ReviewedDependencyManifest.php';
require_once __DIR__ . '/ReviewedDependencyCatalog.php';
require_once __DIR__ . '/ReviewedDependencyEntry.php';
require_once __DIR__ . '/ReviewedDependencyCoverage.php';
require_once __DIR__ . '/MagoSource.php';

// Explicit physical catalog of actual lint/verify inputs, never generated by verification.
/** @return array<string, \Tablo\Tools\ReviewedDependencyCatalog::Metadata> */
function worker_dependencies(): array
{
    $core = [
        'tools/reviewed-dependency-map.json' => ['owner' => 'Explicit reviewed physical dependency catalog', 'consumers' => ['Composer verify', 'Reviewed dependency capture']],
        'tools/reviewed-dependencies.php' => ['owner' => 'Reviewed dependency guard orchestration', 'consumers' => ['Composer verify', 'Reviewed dependency capture']],
        'tools/ReviewedDependencyManifest.php' => ['owner' => 'Tablo\\Tools\\ReviewedDependencyManifest', 'consumers' => ['Composer verify', 'Reviewed dependency capture']],
        'tools/ReviewedDependencyEntry.php' => ['owner' => 'Tablo\\Tools\\ReviewedDependencyEntry', 'consumers' => ['Composer verify', 'Reviewed dependency capture']],
    ];
    $selected = \Tablo\Tools\ReviewedDependencyCatalog::checked(json_decode(\Tablo\RequiredFile::bytes(file_get_contents(__DIR__ . '/reviewed-dependency-map.json')), associative: true, depth: 32, flags: JSON_THROW_ON_ERROR));
    return $core + $selected;
}

function dependency_hash(string $root, string $path): string
{
    $canonicalRoot = realpath($root);
    if ($canonicalRoot === false) { throw new RuntimeException('Invalid reviewed dependency root.'); }
    $expected = str_replace('\\', replace: '/', subject: $canonicalRoot) . '/' . $path;
    $actual = realpath($root . '/' . $path);
    if ($actual === false || str_replace('\\', replace: '/', subject: $actual) !== $expected || !is_file($actual)) {
        throw new RuntimeException('Invalid reviewed dependency path: ' . $path);
    }
    return 'sha256:' . \Tablo\RequiredFile::digest($actual);
}

function verify_worker_dependencies(string $root): void
{
    $required = worker_dependencies();
    $entries = \Tablo\Tools\ReviewedDependencyManifest::read($root, count($required));
    $index = 0;
    foreach ($required as $path => $metadata) {
        if (!array_key_exists($index, $entries)) { throw new RuntimeException('Missing reviewed dependency entry.'); }
        \Tablo\Tools\ReviewedDependencyEntry::verify($entries[$index], $path, $metadata, $root);
        ++$index;
    }
    \Tablo\Tools\ReviewedDependencyCoverage::verify($root, $required);
}

/** @return array<string, \Tablo\Tools\ReviewedDependencyCatalog::Metadata> */
function required_reviewed_dependencies(): array { return worker_dependencies(); }
function check_reviewed_dependencies(string $root): void { verify_worker_dependencies($root); }
